// Package cardinaloperator holds the logic and embedded manifests world-cli
// uses to run shards on a local k3d cluster through cardinal-operator.
//
// It lives at cli/pkg/k8s/cardinal-operator/ — under the pkg/k8s/ namespace, and
// the Go package identifier drops the hyphen, as Go requires.
//
// The contents of manifests/ are version-pinned copies of artifacts owned by
// other components — today the ShardPool CRD generated by cardinal-operator,
// later the operator/NATS/gateway manifests. They are kept in sync by CI on
// each cardinal-operator release; do not hand-edit them.
package cardinaloperator

import "embed"

// Manifests is the embedded YAML bundle applied during cluster bootstrap:
// the ShardPool CRD, the operator's Deployment + RBAC, the shared NATS
// instance (with JetStream PVC), and the gateway. world-cli applies these in
// order before any project-specific resources.
//
//go:embed manifests
var Manifests embed.FS
